jQuery(document).ready(function($){function limpa_formulário_cep(){$("#billing_address_1").val("");$("#billing_neighborhood").val("");$("#billing_city").val("");$("#billing_state").val("").trigger("change")}function resolveShippingCalculator(){const $calculator=$(".gstore-shipping-calculator");if(!$calculator.length){return null}return $calculator}function showShippingError(message){const $calculator=resolveShippingCalculator();if(!$calculator){return}const $error=$calculator.find(".gstore-shipping-calculator__error");if($error.length){$error.html('<i class="fa-solid fa-exclamation-circle" aria-hidden="true"></i> '+message);$error.addClass("is-visible")}$calculator.addClass("has-error");$calculator.find(".gstore-shipping-calculator__cep").addClass("has-error")}function clearShippingError(){const $calculator=resolveShippingCalculator();if(!$calculator){return}const $error=$calculator.find(".gstore-shipping-calculator__error");if($error.length){$error.removeClass("is-visible").html("")}$calculator.removeClass("has-error");$calculator.find(".gstore-shipping-calculator__cep").removeClass("has-error")}$("#billing_postcode").blur(function(){var cep=$(this).val().replace(/\D/g,"");if(cep!=""){var validacep=/^[0-9]{8}$/;if(validacep.test(cep)){clearShippingError();$("#billing_address_1").val("...");$("#billing_neighborhood").val("...");$("#billing_city").val("...");$("#billing_state").val("...");$.getJSON("https://viacep.com.br/ws/"+cep+"/json/?callback=?",function(dados){if(!("erro"in dados)){$("#billing_address_1").val(dados.logradouro);$("#billing_neighborhood").val(dados.bairro);$("#billing_city").val(dados.localidade);$("#billing_state").val(dados.uf).trigger("change");$("#billing_number").focus();clearShippingError()}else{limpa_formulário_cep();showShippingError("CEP não encontrado.")}})}else{limpa_formulário_cep();showShippingError("Formato de CEP inválido.")}}else{limpa_formulário_cep();clearShippingError()}})});
